typedef unsigned short vert_ref;
typedef unsigned short face_ref;
typedef unsigned short material_ref;

class vector3d
{
public:
  float x;
  float y;
  float z;
};

class po
{
public:
  vector3d slow_xform(const vector3d&) const;
  vector3d non_affine_slow_xform(const vector3d&) const;
};

class vert
{
public:
  vert(const vector3d& _point) : point(_point) { num_bones=0; }
  const vector3d& get_point() const { return point; }

  vector3d point __attribute__((aligned(16)));
  int num_bones;
  unsigned char bone_ids[4];
  float bone_weights[4];
};

class cface
{
public:
  const vector3d& get_raw_normal() const { return raw_normal; }
  void set_normal(vector3d v) { normal = v; }
  const vector3d& get_raw_center() const { return raw_center; }
  void set_center(vector3d c) { center = c; }

private:
  vert_ref vert_refs[3];
  material_ref my_material;
  vector3d raw_normal;
  vector3d normal __attribute__((aligned(16)));
  vector3d raw_center;
  vector3d center;
  float radius;
  unsigned short flags;
};

template<class T>
class vector
{
public:
  T* begin_;
  T* end_;
  T* capacity_;

  T& operator[](unsigned int i) { return begin_[i]; }
  const T& operator[](unsigned int i) const { return begin_[i]; }
  unsigned int size() const { return end_ - begin_; }
};

class collision_geometry
{
  char layout[12];
public:
  void xform(po const& the_po);
};

class cg_mesh : public collision_geometry
{
public:
  const vert& get_raw_vert(vert_ref i) const { return raw_verts[i]; }
  const cface& get_cface(face_ref i) const { return cfaces[i]; }
  void set_vert(int i, vert v) { verts[i] = v; }
  int get_num_verts() const { return verts.size(); }
  int get_num_cfaces() const { return cfaces.size(); }
  void xform(po const& the_po);

protected:
  vector<vert> raw_verts;
  vector<vert> verts;
  vector<cface> cfaces;
};

void cg_mesh::xform(po const & the_po)
{
  int i;
  collision_geometry::xform(the_po);
  for (i=0; i<get_num_verts(); ++i)
  {
    vert v(the_po.slow_xform(get_raw_vert(i).get_point()));
    set_vert(i,v);
  }
  for (i=0; i<get_num_cfaces(); ++i)
  {
    vector3d v = the_po.non_affine_slow_xform(get_cface(i).get_raw_normal());
    cfaces[i].set_normal(v);
    v = the_po.slow_xform(get_cface(i).get_raw_center());
    cfaces[i].set_center(v);
  }
}
